def spring(config, action, extra=''):
 return '//DEPS org.springframework:spring-context:6.1.14\nimport org.springframework.context.annotation.*;\nimport org.springframework.beans.factory.annotation.Value;\npublic class Lesson {\n'+extra+'\n@Configuration\nstatic class Config {\n'+config+'\n}\npublic static void main(String[] args) {\n try (var context = new AnnotationConfigApplicationContext(Config.class)) {\n'+action+'\n }\n}\n}\n'
def boot(methods):
 return '//DEPS org.springframework.boot:spring-boot-starter-web:3.3.5\nimport org.springframework.boot.*;\nimport org.springframework.boot.autoconfigure.*;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.web.bind.annotation.*;\nimport org.springframework.http.*;\nimport java.util.*;\n@SpringBootConfiguration\n@EnableAutoConfiguration\n@Import(Lesson.Web.class)\npublic class Lesson {\n public static void main(String[] args) { SpringApplication.run(Lesson.class, args); }\n @RestController\n static class Web {\n'+methods+'\n }\n}\n'
course('spring-framework','Spring Framework','java','Examples use Spring Framework 6.1, Java 17 or later, and JBang.','Install Java 17 or later and JBang. Save each example as Lesson.java and run jbang Lesson.java. The //DEPS line lets JBang fetch Spring. These examples use the core container and do not start a web server.','Spring Framework can create and connect objects for a Java program. Its container looks after these shared objects, called beans.',[
L('first-bean','Create a managed value','@Bean marks a value that Spring creates. The context is a container that lets the program find that value.',spring('@Bean String message() { return "Hello, Asha!"; }','System.out.println(context.getBean(String.class));'),'Hello, Asha!','Change the message bean.','Close the context when the program is finished.'),
L('bean-names','Find a bean by name','The method name becomes the bean name. This example asks for the bean called school.',spring('@Bean String school() { return "Oak School"; }','System.out.println(context.getBean("school", String.class));'),'Oak School','Rename the method and the lookup together.','The requested name must match a registered bean.'),
L('two-beans','Choose between two values','A container can hold several beans of one type. A name selects the one you need.',spring('@Bean String red() { return "red"; }\n@Bean String blue() { return "blue"; }','System.out.println(context.getBean("blue", String.class));'),'blue','Ask for red instead.','A lookup by type alone is ambiguous when two beans match.'),
L('dependencies','Connect two objects','Spring can pass one bean into another bean method. This is dependency injection: the object receives what it needs.',spring('@Bean Score score() { return new Score(4); }\n@Bean Badge badge(Score score) { return new Badge(score); }','System.out.println(context.getBean(Badge.class).value());','record Score(int value) {}\nrecord Badge(Score score) { int value() { return score.value() * 2; } }'),'8','Change the Score value to 7.','Declare the needed dependency instead of creating a second hidden copy.'),
L('singleton','Share one bean instance','The normal Spring scope is singleton: one instance per bean definition in the container.',spring('@Bean Object box() { return new Object(); }','System.out.println(context.getBean("box") == context.getBean("box"));'),'true','Compare a separately created new Object too.','Singleton means one per container bean definition, not one in every program everywhere.'),
L('prototype','Ask for a fresh instance','Prototype scope makes a new bean each time the container is asked for it.',spring('@Bean @Scope("prototype") Object box() { return new Object(); }','System.out.println(context.getBean("box") == context.getBean("box"));'),'false','Remove @Scope and compare.','Spring does not manage full destruction of prototype instances for you.'),
L('lazy','Create a bean when needed','@Lazy delays this bean until it is requested. The print inside its factory shows when creation happens.',spring('@Bean @Lazy String message() { System.out.println("Made now"); return "Hello"; }','System.out.println("Before request");\ncontext.getBean("message");'),'Before request\nMade now','Remove @Lazy and compare the order.','Lazy creation delays work; it does not remove that work.'),
L('default-values','Read a configured value','@Value can read a property with a fallback. No lesson.score property is set, so the fallback is 8.',spring('@Bean Integer score(@Value("$'+'{lesson.score:8}") int score) { return score; }','System.out.println(context.getBean(Integer.class));'),'8','Change the fallback to 6.','A fallback is used only when the property is missing.'),
L('initialisation','Run a setup method','initMethod names a method Spring calls after making the bean.',spring('@Bean(initMethod="prepare") Note note() { return new Note(); }','System.out.println(context.getBean(Note.class).text);','static class Note { String text; public void prepare() { text = "Ready"; } }'),'Ready','Change the setup text.','The named method must exist and be callable with no arguments.'),
L('cleanup','Run cleanup when closing','destroyMethod names cleanup. Closing the context runs it for this singleton bean.',spring('@Bean(destroyMethod="close") Note note() { return new Note(); }','','static class Note { public void close() { System.out.println("Closed"); } }'),'Closed','Add a print before the context closes and compare order.','Cleanup needs the context to close; an abrupt process stop may skip it.'),
L('primary','Choose a default bean','@Primary marks the preferred bean when several beans match a type.',spring('@Bean String red() { return "red"; }\n@Bean @Primary String blue() { return "blue"; }','System.out.println(context.getBean(String.class));'),'blue','Move @Primary to red.','Only one matching bean should be the primary choice.'),
L('bean-lookup','Check whether a bean exists','containsBean lets code check a registered name before trying to read it.',spring('@Bean String message() { return "Hello"; }','System.out.println(context.containsBean("message"));'),'true','Check the name missing instead.','A name check does not validate every future operation on the bean.')])
course('spring-boot','Spring Boot','java','Examples use Spring Boot 3.3.5, Java 17 or later, and JBang.','Install Java 17 or later and JBang. Save one example as Lesson.java and run jbang Lesson.java. JBang downloads the dependency on the //DEPS line. Use http://127.0.0.1:8080 and stop the server before another example.','Spring Boot starts a Spring application with ready-made defaults. These lessons build tiny HTTP endpoints without a database.',[
L('first-route','Return a greeting','@RestController makes return values into HTTP responses. GET /hello calls this method.',boot('@GetMapping("/hello") String hello() { return "Hello, Asha!"; }'),'Hello, Asha!','Change the message.','A mapping must use the same path and HTTP method as the request.'),
L('json','Return named data','Spring Boot writes a Map as JSON. Open GET /book.',boot('@GetMapping("/book") Map<String, Object> book() { return Map.of("title", "Moon Trip"); }'), '{"title":"Moon Trip"}','Add another field.','JSON object field order is not part of its meaning.'),
L('path-inputs','Read a path value','@PathVariable reads a value from a named path position. Open GET /hello/Ravi.',boot('@GetMapping("/hello/{name}") String hello(@PathVariable("name") String name) { return "Hi, " + name + "!"; }'),'Hi, Ravi!','Visit /hello/Asha.','Use the explicit input name so compilation settings do not affect binding.'),
L('query-defaults','Use a query default','@RequestParam reads a query value. GET /page without n uses the default 1.',boot('@GetMapping("/page") Map<String, Integer> page(@RequestParam(name="n", defaultValue="1") int n) { return Map.of("page", n); }'), '{"page":1}','Visit /page?n=3.','Text that cannot become an int is rejected before this method runs.'),
L('typed-paths','Parse a whole number','An int path input is parsed by Spring. Open GET /double/4.',boot('@GetMapping("/double/{n}") Map<String, Integer> twice(@PathVariable("n") int n) { return Map.of("answer", n * 2); }'), '{"answer":8}','Try /double/cat.','A type checks the shape, not whether the number fits your business rule.'),
L('request-bodies','Read a JSON body','@RequestBody reads JSON into a Java record. Send POST /books with application/json and {"title":"Moon Trip"}.',boot('record Book(String title) {}\n@PostMapping("/books") Book create(@RequestBody Book book) { return book; }'), '{"title":"Moon Trip"}','Change the posted title.','A record defines fields but does not automatically make every value valid.'),
L('validation','Reject a missing title','A handler can check a body value and send 400 when it is not usable. Send POST /books with {"title":"Moon Trip"}.',boot('record Book(String title) {}\n@PostMapping("/books") ResponseEntity<?> create(@RequestBody Book book) {\n if (book.title() == null || book.title().isBlank()) return ResponseEntity.badRequest().body(Map.of("error", "Title needed"));\n return ResponseEntity.status(201).body(book);\n}'), '{"title":"Moon Trip"}','Send an empty title and inspect 400.','Check input before storing or acting on it.'),
L('status','Report a missing resource','ResponseEntity lets code choose a status and body. Open GET /missing.',boot('@GetMapping("/missing") ResponseEntity<?> missing() { return ResponseEntity.status(404).body(Map.of("error", "Book not found")); }'), '{"error":"Book not found"}','Inspect the status with curl -i.','A failure should not use a success status just because it has a body.'),
L('lists','Return several records','A list becomes a JSON array. Open GET /books.',boot('@GetMapping("/books") List<String> books() { return List.of("Moon Trip", "Sun Trip"); }'), '["Moon Trip","Sun Trip"]','Add a third title.','List.of makes a list that cannot be changed in place.'),
L('headers','Set reply metadata','A response can carry cache instructions. Open GET /note and inspect Cache-Control.',boot('@GetMapping("/note") ResponseEntity<String> note() { return ResponseEntity.ok().header("Cache-Control", "no-store").body("Practice note"); }'),'Practice note','Use curl -i to see the header.','Headers need to be set before the response is sent.'),
L('redirects','Return a location','A 302 reply with Location asks a browser to make another request. GET /start ends at /hello.',boot('@GetMapping("/start") ResponseEntity<Void> start() { return ResponseEntity.status(302).header("Location", "/hello").build(); }\n@GetMapping("/hello") String hello() { return "Welcome"; }'),'Welcome','Inspect the first reply without following redirects.','Redirects are client actions, not calls to another Java method.'),
L('exception-handler','Handle a known failure','@ExceptionHandler formats one error type for this controller. Open GET /broken.',boot('@GetMapping("/broken") String broken() { throw new IllegalStateException("Practice failure"); }\n@ExceptionHandler(IllegalStateException.class) ResponseEntity<?> failure() { return ResponseEntity.status(500).body(Map.of("error", "Try again later")); }'), '{"error":"Try again later"}','Change the public message.','Do not expose private stack traces or internal values in error replies.')])
